import os
import subprocess
import sys

def git_show(stage, path):
    res = subprocess.run(["git", "show", ":" + str(stage) + ":" + path], capture_output=True)
    if res.returncode != 0:
        return None
    return res.stdout

def line_key(line):
    s = line.decode("utf-8", "surrogateescape").strip()
    if not s or s.startswith("#"):
        return None
    if s[0] in ("\"", "'"):
        q = s[0]
        end = s.find(q, 1)
        inner = s[1:end] if end != -1 else s[1:]
        parts = inner.split()
        return parts[0] if parts else s
    if "=" in s:
        return s.split("=", 1)[0].strip()
    if s in ("]",):
        return None
    return s.split()[0]

def merge_hunk(base, ours, theirs):
    base_set = set(base)
    ours_set = set(ours)
    base_by_key = dict()
    for line in base:
        k = line_key(line)
        if k is not None and k not in base_by_key:
            base_by_key[k] = line
    ours_by_key = dict()
    for line in ours:
        k = line_key(line)
        if k is not None and k not in ours_by_key:
            ours_by_key[k] = line

    result = list(ours)
    replacements = dict()
    additions = list()

    for idx, line in enumerate(theirs):
        if line in base_set or line in ours_set:
            continue
        k = line_key(line)
        if k is None:
            additions.append((idx, line))
            continue
        if k in ours_by_key:
            ours_line = ours_by_key[k]
            base_line = base_by_key.get(k)
            if base_line is not None and ours_line == base_line:
                pos = result.index(ours_line)
                replacements[pos] = line
            continue
        if k in base_by_key:
            continue
        additions.append((idx, line))

    placements = list()
    for idx, line in additions:
        pos = 0
        for j in range(idx - 1, -1, -1):
            prev = theirs[j]
            if prev in ours_set:
                pos = ours.index(prev) + 1
                break
        placements.append((pos, line))

    for pos, line in replacements.items():
        result[pos] = line
    for pos, line in reversed(placements):
        result.insert(pos, line)
    return result

def resolve_text(data):
    lines = data.splitlines(keepends=True)
    out = list()
    i = 0
    while i < len(lines):
        line = lines[i]
        if line.startswith(b"<<<<<<<"):
            i += 1
            ours = list()
            while i < len(lines) and not lines[i].startswith(b"|||||||"):
                ours.append(lines[i])
                i += 1
            if i >= len(lines):
                out.append(b"<<<<<<<\n")
                out.extend(ours)
                break
            i += 1
            base = list()
            while i < len(lines) and lines[i].rstrip(b"\r\n") != b"=======":
                base.append(lines[i])
                i += 1
            if i < len(lines):
                i += 1
            theirs = list()
            while i < len(lines) and not lines[i].startswith(b">>>>>>>"):
                theirs.append(lines[i])
                i += 1
            if i < len(lines):
                i += 1
            out.extend(merge_hunk(base, ours, theirs))
        else:
            out.append(line)
            i += 1
    return b"".join(out)

def main():
    res = subprocess.run(["git", "diff", "--name-only", "--diff-filter=U", "-z"], capture_output=True, check=True)
    raw_paths = res.stdout.split(b"\0")
    paths = [p for p in raw_paths if p]
    for path_b in paths:
        path = os.fsdecode(path_b)
        base = git_show(1, path)
        ours = git_show(2, path)
        theirs = git_show(3, path)
        if ours is None:
            subprocess.run(["git", "rm", "-f", "--", path], check=True)
            continue
        if theirs is None:
            subprocess.run(["git", "add", "--", path], check=True)
            continue
        if base is None:
            base = b""
        try:
            with open(path, "rb") as f:
                data = f.read()
        except FileNotFoundError:
            data = ours
        resolved = resolve_text(data)
        with open(path, "wb") as f:
            f.write(resolved)
        subprocess.run(["git", "add", "--", path], check=True)
    res = subprocess.run(["git", "diff", "--name-only", "--diff-filter=U", "-z"], capture_output=True, check=True)
    if any(p for p in res.stdout.split(b"\0")):
        sys.exit("unmerged paths remain")

if __name__ == "__main__":
    main()
